@@ -38,16 +38,16 @@
 FIRST="${SHUFFLED[0]}"
 SECOND="${SHUFFLED[1]:-}"

 echo "Starting playback: first track (will transition to second track): ${FIRST}"
-ffplay -nodisp -autoexit -loglevel error "$FIRST" || {
+SDL_AUDIODRIVER=dummy ffplay -nodisp -autoexit -loglevel error "$FIRST" || {
   echo "Error playing first track: ${FIRST}" >&2
   exit 1
 }

 if [ -n "$SECOND" ]; then
   echo "Advancing playback to second track: ${SECOND}"
-  ffplay -nodisp -autoexit -loglevel error "$SECOND" || {
+  SDL_AUDIODRIVER=dummy ffplay -nodisp -autoexit -loglevel error "$SECOND" || {
     echo "Error playing second track: ${SECOND}" >&2
     exit 1
   }
 else

